window.lookupMcCheyneByDateIso = function (dateIso) {
  if (!dateIso || dateIso.length < 10) return null;
  var mmdd = dateIso.slice(5, 10);
  return window.MCCHEYNE_365_MAP[mmdd] || null;
};

