window.analyzeBibleReadingPattern = function (entries, targetDateIso, studentType) {
  var list = Array.isArray(entries) ? entries.filter(function (e) { return e && e.date; }) : [];
  var sorted = list.slice().sort(function (a, b) { return a.date.localeCompare(b.date); });
  var uniqueDates = [];
  var dateMap = {};

  sorted.forEach(function (item) {
    if (!dateMap[item.date]) {
      dateMap[item.date] = [];
      uniqueDates.push(item.date);
    }
    dateMap[item.date].push(item);
  });

  var baseDate = targetDateIso ? new Date(targetDateIso + "T00:00:00") : new Date();
  var tomorrow = new Date(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate() + 1);
  var tomorrowIso = tomorrow.getFullYear() + "-" +
    String(tomorrow.getMonth() + 1).padStart(2, "0") + "-" +
    String(tomorrow.getDate()).padStart(2, "0");
  var dayLabels = ["일", "월", "화", "수", "목", "금", "토"];
  var tomorrowWeekday = dayLabels[tomorrow.getDay()];

  if (uniqueDates.length === 0) {
    var defaultBook = studentType === "ELEMENTARY" ? "잠언 1장 (1장)" : "마가복음 1~2장 (2장)";
    var defaultTime = studentType === "ELEMENTARY" ? "오후 4시 00분" : "밤 10시 00분";
    return {
      totalDays: 0,
      avgIntervalDays: 0,
      avgChaptersPerSession: studentType === "ELEMENTARY" ? 1 : 2,
      strongDaysText: "기록 수집 중",
      weakDaysText: "매일 10분 루틴 시작",
      preferredTimeSlot: defaultTime,
      patternSummary: "아직 성경읽기 누적 기록이 없습니다. 오늘부터 날짜별 읽기 패턴을 기록해 보세요.",
      nextDaySuggestion: "내일(" + tomorrowIso + ", " + tomorrowWeekday + ") " + defaultTime + ": " + defaultBook + " 읽고 체크하기"
    };
  }

  // 1. 요일 분포 및 평균 간격 분석
  var weekdayCounts = [0, 0, 0, 0, 0, 0, 0];
  uniqueDates.forEach(function (dStr) {
    var dt = new Date(dStr + "T00:00:00");
    if (!isNaN(dt.getTime())) weekdayCounts[dt.getDay()]++;
  });

  var intervalSum = 0;
  var intervalCount = 0;
  for (var i = 1; i < uniqueDates.length; i++) {
    var prev = new Date(uniqueDates[i - 1] + "T00:00:00");
    var curr = new Date(uniqueDates[i] + "T00:00:00");
    var diffDays = Math.round((curr - prev) / 86400000);
    if (diffDays > 0) {
      intervalSum += diffDays;
      intervalCount++;
    }
  }
  var avgInterval = intervalCount > 0 ? Number((intervalSum / intervalCount).toFixed(1)) : 1;

  var strongDays = [];
  var weakDays = [];
  var maxWd = Math.max.apply(null, weekdayCounts);
  dayLabels.forEach(function (lbl, idx) {
    if (weekdayCounts[idx] > 0 && weekdayCounts[idx] >= Math.max(1, Math.floor(maxWd * 0.6))) {
      strongDays.push(lbl);
    } else if (weekdayCounts[idx] === 0) {
      weakDays.push(lbl);
    }
  });

  // 2. 시간대(KST) 패턴 분석
  var kstHours = [];
  sorted.forEach(function (item) {
    if (item.completedAt) {
      var ts = new Date(item.completedAt);
      if (!isNaN(ts.getTime())) {
        var kstHour = (ts.getUTCHours() + 9) % 24;
        kstHours.push(kstHour);
      }
    }
  });
  var preferredTimeSlot = studentType === "ELEMENTARY" ? "방과후(오후 4시~5시)" : "저녁~밤 시간대";
  var recommendedTime = studentType === "ELEMENTARY" ? "오후 4시 30분" : "밤 10시 00분";
  if (kstHours.length > 0) {
    var hourBuckets = { morning: 0, afternoon: 0, evening: 0, night: 0 };
    var sumH = 0;
    kstHours.forEach(function (h) {
      sumH += h;
      if (h >= 5 && h < 12) hourBuckets.morning++;
      else if (h >= 12 && h < 18) hourBuckets.afternoon++;
      else if (h >= 18 && h < 22) hourBuckets.evening++;
      else hourBuckets.night++;
    });
    var avgHour = Math.round(sumH / kstHours.length);
    if (hourBuckets.night >= hourBuckets.evening && hourBuckets.night >= hourBuckets.morning) {
      preferredTimeSlot = "밤 마감 시간대 (평균 " + avgHour + "시경)";
      recommendedTime = avgHour >= 23 ? "밤 10시 30분 (취침 30분 전)" : "밤 " + (avgHour > 12 ? avgHour - 12 : avgHour) + "시";
    } else if (hourBuckets.morning >= hourBuckets.afternoon) {
      preferredTimeSlot = "오전/아침 시간대 (평균 " + avgHour + "시경)";
      recommendedTime = "오전 " + avgHour + "시";
    } else if (hourBuckets.afternoon >= hourBuckets.evening) {
      preferredTimeSlot = "오후 시간대 (평균 " + (avgHour - 12) + "시경)";
      recommendedTime = "오후 " + (avgHour > 12 ? avgHour - 12 : avgHour) + "시";
    } else {
      preferredTimeSlot = "저녁 시간대 (평균 " + (avgHour - 12) + "시경)";
      recommendedTime = "저녁 " + (avgHour > 12 ? avgHour - 12 : avgHour) + "시";
    }
  }

  // 3. 최근 읽은 분량 & 마지막 본문 기반 다음 날 진도 계산
  var totalChapters = 0;
  uniqueDates.forEach(function (d) {
    var dayCh = dateMap[d].reduce(function (s, it) { return s + (Number(it.chaptersCount) || 1); }, 0);
    totalChapters += dayCh;
  });
  var avgChapters = Math.max(1, Math.round(totalChapters / uniqueDates.length));

  // 마지막 기록에서 직접 책+장 파싱 시도 (예: "잠언 5장", "누가복음 1장", "창세기 3-4장")
  var lastEntry = sorted[sorted.length - 1];
  var lastText = String((lastEntry && (lastEntry.passage || lastEntry.title)) || "");
  var matchedBook = null;
  var lastEndChapter = 0;

  var booksSortedByLen = window.BIBLE_66_BOOKS.slice().sort(function (a, b) { return b.name.length - a.name.length; });
  for (var bi = 0; bi < booksSortedByLen.length; bi++) {
    var book = booksSortedByLen[bi];
    var idx = lastText.lastIndexOf(book.name);
    if (idx >= 0) {
      var after = lastText.slice(idx + book.name.length);
      var chMatch = after.match(/^\s*(\d+)(?:\s*[-~]\s*(\d+))?/);
      if (chMatch) {
        matchedBook = book;
        lastEndChapter = Number(chMatch[2] || chMatch[1]);
        break;
      }
    }
  }

  var nextPassageText = "";
  var paceTarget = studentType === "ELEMENTARY" ? Math.min(2, avgChapters) : Math.min(4, Math.max(2, avgChapters));

  if (matchedBook && lastEndChapter > 0) {
    var nextStart = lastEndChapter + 1;
    var targetBook = matchedBook;
    if (nextStart > matchedBook.chapters) {
      var nextIdx = matchedBook.no; // 1-based -> next index in 0-based array
      targetBook = window.BIBLE_66_BOOKS[nextIdx % window.BIBLE_66_BOOKS.length];
      nextStart = 1;
    }
    var nextEnd = Math.min(targetBook.chapters, nextStart + paceTarget - 1);
    nextPassageText = nextEnd > nextStart
      ? targetBook.name + " " + nextStart + "~" + nextEnd + "장 (" + (nextEnd - nextStart + 1) + "장)"
      : targetBook.name + " " + nextStart + "장 (1장)";
  } else {
    var mcTomorrow = window.lookupMcCheyneByDateIso(tomorrowIso);
    nextPassageText = mcTomorrow
      ? mcTomorrow.passages + " 중 핵심 " + paceTarget + "장"
      : "복음서/잠언 이어 읽기 " + paceTarget + "장";
  }

  var strongText = strongDays.length ? strongDays.join("·") : "고른 분포";
  var weakText = weakDays.length ? weakDays.slice(0, 3).join("·") : "없음";
  var patternSummary = "평균 " + avgInterval + "일 간격 · 주력 요일(" + strongText + ") · " + preferredTimeSlot + " · 회당 평균 " + avgChapters + "장";

  var gapAdvice = avgInterval > 1.6
    ? " (공백 요일 '" + weakText + "'에 10분 먼저 열기!)"
    : " (매일 루틴 안정적!)";

  var nextDaySuggestion = "내일(" + tomorrowWeekday + ") " + recommendedTime + ": " + nextPassageText + gapAdvice;

  return {
    totalDays: uniqueDates.length,
    avgIntervalDays: avgInterval,
    avgChaptersPerSession: avgChapters,
    strongDaysText: strongText,
    weakDaysText: weakText,
    preferredTimeSlot: preferredTimeSlot,
    recommendedTime: recommendedTime,
    patternSummary: patternSummary,
    nextDaySuggestion: nextDaySuggestion
  };
};
